+
+static REString *re_string_find(REStringList *s, int len, const uint32_t *buf,
+                                BOOL add_flag)
+{
+    uint32_t h0;
+    h0 = re_string_hash(len, buf);
+    return re_string_find2(s, len, buf, h0, add_flag);
+}
